const results = [];

for (const item of $input.all()) {
  // 1. جلب مخرجات AI Agent
  const rawOutput = item.json.output || "";

  // 2. تنظيف Markdown إن وُجد
  const jsonString = rawOutput
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  let data = {};

  try {
    data = JSON.parse(jsonString);
  } catch (error) {
    results.push({
      json: {
        error: "Failed to parse JSON",
        errorMessage: error.message,
        rawOutput: rawOutput
      }
    });

    continue;
  }

  // 3. تصنيف الـ Scores
  const getScoreLabel = (value) => {
    if (value >= 85) return "Excellent";
    if (value >= 70) return "Good";
    if (value >= 50) return "Moderate";
    return "Weak";
  };

  // 4. تحويل scores إلى Array
  const scores = data.scores
    ? Object.entries(data.scores).map(([key, value]) => ({
        name: key
          .split("_")
          .map(word => word.charAt(0).toUpperCase() + word.slice(1))
          .join(" "),
        value: Number(value),
        label: getScoreLabel(Number(value))
      }))
    : [];

  // 5. بناء الـ JSON النهائي
  results.push({
    json: {
      // Basic Information
      ideaName: data.idea_name || "Startup Idea",
      title: "Idea Analysis",
      summary: data.summary || "",

      // Problem & Solution
      problem: data.problem || "",
      solution: data.solution || "",
      valueProposition: data.value_proposition || "",
      targetCustomer: data.target_customer || "",

      // Overall Scores
      scores: scores,

      // Problem Validation
      problemAnalysis: {
        intensityScore: Number(
          data.problem_analysis?.intensity_score || 0
        ),
        frequency: data.problem_analysis?.frequency || "",
        currentAlternatives:
          data.problem_analysis?.current_alternatives || "",
        willingnessToPay:
          data.problem_analysis?.willingness_to_pay || "",
        marketPotential:
          data.problem_analysis?.market_potential || "",
        isWorthSolving:
          data.problem_analysis?.is_worth_solving || "",
        reasoning:
          data.problem_analysis?.reasoning || ""
      },

      problemScore: Number(data.problem_score || 0),
      isWorthSolving: data.is_worth_solving || "",
      problemValidationSummary:
        data.problem_validation_summary || "",

      // Target Customer Analysis
      customerAnalysis: {
        customerProfile:
          data.customer_analysis?.customer_profile || "",
        ageRangeGender:
          data.customer_analysis?.age_range_gender || "",
        geographicScope:
          data.customer_analysis?.geographic_scope || "",
        socioeconomicProfile:
          data.customer_analysis?.socioeconomic_profile || "",
        knowledgeTechSavviness:
          data.customer_analysis?.knowledge_tech_savviness || "",
        behavioralPsychologicalProfile:
          data.customer_analysis?.behavioral_psychological_profile || "",
        b2bContext:
          data.customer_analysis?.b2b_context || "",
        customerAcquisitionEase:
          data.customer_analysis?.customer_acquisition_ease || ""
      },

      // Customer Analysis - Simplified Fields
      targetCustomerProfile:
        data.target_customer_profile || "",

      customerDemographics:
        data.customer_demographics || "",

      customerSocioeconomicProfile:
        data.customer_socioeconomic_profile || "",

      customerBehavioralProfile:
        data.customer_behavioral_profile || "",

      customerAcquisitionEase:
        data.customer_acquisition_ease || "",

      // Solution Evaluation
      solutionEvaluation:
        data.solution_evaluation || "",

      // General Analysis
      strengths: Array.isArray(data.strengths)
        ? data.strengths
        : [],

      weaknesses: Array.isArray(data.weaknesses)
        ? data.weaknesses
        : [],

      assumptions: Array.isArray(data.assumptions)
        ? data.assumptions
        : [],

      questions: Array.isArray(data.key_questions)
        ? data.key_questions
        : [],

      // Final Evaluation
      overallIdeaScore:
        Number(data.overall_idea_score || 0),

      finalRecommendation:
        data.final_recommendation || "",

      verdict:
        data.verdict || "",

      verdictReason:
        data.verdict_reason || ""
    }
  });
}

return results;
